import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {(project_basename, framework, package_id): resolved_version}
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                lookup[(name, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        status = 'Aligned to highest version' if bv and av else ('Added' if not bv else 'Removed')
        changes.append((k[0], k[1], k[2], bv or '-', av or '-', status))
    else:
        unchanged.append((k[0], k[1], k[2], av))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]:20s} {c[1]:10s} {c[2]:50s} {c[3]:12s} -> {c[4]:12s} ({c[5]})')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]:20s} {u[1]:10s} {u[2]:50s} {u[3]}')
"

